-- EduNova v0.20.0 LOT 19 — Intelligent Remediation Engine
CREATE TABLE IF NOT EXISTS remediation_misconceptions (id VARCHAR(64) PRIMARY KEY,account_id VARCHAR(64) NOT NULL,course_id VARCHAR(64) NOT NULL,chapter_id VARCHAR(64),concept_id VARCHAR(128) NOT NULL,label VARCHAR(255) NOT NULL,evidence TEXT NOT NULL,bloom_gap VARCHAR(24) NOT NULL,severity INTEGER NOT NULL CHECK(severity BETWEEN 0 AND 100),confidence INTEGER NOT NULL CHECK(confidence BETWEEN 0 AND 100),state VARCHAR(24) NOT NULL CHECK(state IN ('open','improving','resolved')),created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,row_version INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS ix_remediation_misconceptions_priority ON remediation_misconceptions(account_id,state,severity DESC);
CREATE TABLE IF NOT EXISTS remediation_paths (id VARCHAR(64) PRIMARY KEY,account_id VARCHAR(64) NOT NULL,misconception_id VARCHAR(64) NOT NULL,course_id VARCHAR(64) NOT NULL,chapter_id VARCHAR(64),steps TEXT NOT NULL,current_step INTEGER NOT NULL DEFAULT 0,status VARCHAR(24) NOT NULL CHECK(status IN ('active','completed','abandoned')),baseline_score INTEGER,verification_score INTEGER,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,row_version INTEGER NOT NULL DEFAULT 1,model_version VARCHAR(32) NOT NULL DEFAULT 'remediation-v1');
CREATE INDEX IF NOT EXISTS ix_remediation_paths_active ON remediation_paths(account_id,status,updated_at DESC);
